#!/usr/bin/env luajit
local bit=require('bit');local band,rshift=bit.band,bit.rshift
local bin={{'ADD','+'},{'SUB','-'},{'MUL','*'},{'XOR','^'}};local opn={PUSH=0,ADD=1,SUB=2,MUL=3,XOR=4,BR_GE=5,JMP=6,HALT=7}
local o={'/* generated */','#include <stdint.h>','typedef uint64_t V; typedef int64_t S;','#define PN __attribute__((preserve_none))','#define ARGS const uint8_t *ip, V *s0, V *s1, V *s2, V *s3','#define PASS ip, s0, s1, s2, s3','typedef PN V (*H)(ARGS);','extern H T[16 * 256];','struct fin { V *s[4]; } fin_r;','#define NEXT [[clang::musttail]] return T[((ip[0] & 15) << 8) | ip[1]](PASS);','static inline int16_t rd16(const uint8_t *p) { int16_t v; __builtin_memcpy(&v, p, 2); return v; }','static PN V bad(ARGS) { return 255; }'}
local names={};local function key(op,r)return op..':'..r end;local function dec(r)return band(r,3),band(rshift(r,2),3),band(rshift(r,4),3),band(rshift(r,6),1),band(rshift(r,7),1)end
for _,pair in ipairs(bin)do local op,sym=pair[1],pair[2];for r=0,255 do local l,rr,d,kl,kr=dec(r);local n='h_'..op..'_'..r;names[key(op,r)]=n;local b={('static PN V %s(ARGS) {'):format(n),('  V x = s%d[-1], y = s%d[-1];'):format(l,rr),('  V r = x %s y;'):format(sym)};if kl==0 then b[#b+1]=('  s%d--;'):format(l)end;if kr==0 and rr~=l then b[#b+1]=('  s%d--;'):format(rr)end;b[#b+1]=('  *s%d = r; s%d++;'):format(d,d);b[#b+1]='  ip += 2; NEXT';b[#b+1]='}';for _,x in ipairs(b)do o[#o+1]=x end end end
for r=0,255 do local l,rr,_,kl,kr=dec(r);local n='h_BR_'..r;names[key('BR_GE',r)]=n;local b={('static PN V %s(ARGS) {'):format(n),('  V x = s%d[-1], y = s%d[-1];'):format(l,rr)};if kl==0 then b[#b+1]=('  s%d--;'):format(l)end;if kr==0 and rr~=l then b[#b+1]=('  s%d--;'):format(rr)end;b[#b+1]='  if ((S)x >= (S)y) ip += 4 + rd16(ip + 2); else ip += 4;';b[#b+1]='  NEXT';b[#b+1]='}';for _,x in ipairs(b)do o[#o+1]=x end end
for d=0,3 do o[#o+1]=('static PN V h_PUSH_%d(ARGS) { *s%d = (V)(S)(int8_t)ip[2]; s%d++; ip += 3; NEXT }'):format(d,d,d)end
for r=0,255 do names[key('PUSH',r)]='h_PUSH_'..band(rshift(r,4),3);names[key('JMP',r)]='h_JMP';names[key('HALT',r)]='h_HALT'end
o[#o+1]='static PN V h_JMP(ARGS) { ip += 4 + rd16(ip + 2); NEXT }';o[#o+1]='static PN V h_HALT(ARGS) { fin_r.s[0]=s0; fin_r.s[1]=s1; fin_r.s[2]=s2; fin_r.s[3]=s3; return 1; }'
local ent={'[0 ... 4095] = bad'};for _,op in ipairs{'PUSH','ADD','SUB','MUL','XOR','BR_GE','JMP','HALT'}do for r=0,255 do ent[#ent+1]=('[%d] = %s'):format(opn[op]*256+r,names[key(op,r)])end end;o[#o+1]='H T[16 * 256] = { '..table.concat(ent,', ')..' };';o[#o+1]='V run_R(const uint8_t *ip, V *a0, V *a1, V *a2, V *a3) { return T[((ip[0] & 15) << 8) | ip[1]](ip, a0, a1, a2, a3); }'
local tail={'typedef PN V (*HD)(const uint8_t *ip, V **sp);','extern HD TD[16];','V *fin_d[4];','#define NEXTD [[clang::musttail]] return TD[ip[0] & 15](ip, sp);','static PN V bad_d(const uint8_t *ip, V **sp) { return 255; }'};for _,x in ipairs(tail)do o[#o+1]=x end
for _,pair in ipairs(bin)do local op,sym=pair[1],pair[2];local lines={('static PN V d_%s(const uint8_t *ip, V **sp) {'):format(op),'  unsigned r = ip[1], L = r & 3, R = (r >> 2) & 3, D = (r >> 4) & 3, kl = (r >> 6) & 1, kr = (r >> 7) & 1;',('  V x = sp[L][-1], y = sp[R][-1]; V v = x %s y;'):format(sym),'  if (!kl) sp[L]--; if (!kr && R != L) sp[R]--;','  *sp[D] = v; sp[D]++; ip += 2; NEXTD','}'};for _,x in ipairs(lines)do o[#o+1]=x end end
local rest={'static PN V d_BR(const uint8_t *ip, V **sp) {','  unsigned r = ip[1], L = r & 3, R = (r >> 2) & 3, kl = (r >> 6) & 1, kr = (r >> 7) & 1;','  V x = sp[L][-1], y = sp[R][-1]; if (!kl) sp[L]--; if (!kr && R != L) sp[R]--;','  if ((S)x >= (S)y) ip += 4 + rd16(ip + 2); else ip += 4; NEXTD','}','static PN V d_PUSH(const uint8_t *ip, V **sp) { unsigned D = (ip[1] >> 4) & 3; *sp[D] = (V)(S)(int8_t)ip[2]; sp[D]++; ip += 3; NEXTD }','static PN V d_JMP(const uint8_t *ip, V **sp) { ip += 4 + rd16(ip + 2); NEXTD }','static PN V d_HALT(const uint8_t *ip, V **sp) { for (int i = 0; i < 4; i++) fin_d[i] = sp[i]; return 1; }','HD TD[16] = { [0 ... 15] = bad_d, [0] = d_PUSH, [1] = d_ADD, [2] = d_SUB, [3] = d_MUL, [4] = d_XOR, [5] = d_BR, [6] = d_JMP, [7] = d_HALT };','V run_D(const uint8_t *ip, V **sp) { return TD[ip[0] & 15](ip, sp); }'};for _,x in ipairs(rest)do o[#o+1]=x end
local out=arg[1] or 'lanes_gen.c';local f=assert(io.open(out,'wb'));assert(f:write(table.concat(o,'\n'),'\n'));assert(f:close());print((7*256)..' table entries, '..(5*256+4+2)..' static handlers')
